SourceCode.Declaration:
/// <summary>
/// XML Formatter class for picking sales orders.
/// </summary>
[TFMTableNameAttribute(tableStr(SalesTable))]
class MobXMLFormatOrders_PickSales extends MobXMLFormatOrders_Pick
{
    SalesTable          salesTable;
}

Method.Source:
protected void setValues()
{
    super();

    salesTable         = common;


    displayLine1            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, SalesId)).Label() + ': ' + salesTable.SalesId;
    displayLine2            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, SalesName)).label() + ': ' + salesTable.SalesName;
    displayLine3            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, DeliveryDate)).label() + ': ' + strfmt('%1',salesTable.DeliveryDate);
    displayLine4            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, SalesType)).label() + ': ' + strfmt('%1',salesTable.SalesType);
    headerLabel1            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, SalesId)).Label();
    headerLabel2            = new DictField(tablenum(SalesTable), fieldnum(SalesTable, SalesName)).label();
    headerValue1            = salesTable.SalesId;
    headerValue2            = salesTable.SalesName;
    sorting                 = strKeep(date2Str(salesTable.DeliveryDate,321,2,0,2,0,2),'1234567890');
    if (MenuItemsConf.exists('CartOverview'))
    {
        MenuItemsConf.remove('CartOverview');
    }
}
